import{U as e,W as t,nt as n,t as r}from"./chunks/framework.BPwQCpO3.js";var i=JSON.parse(`{"title":"ADR-0002: 为什么第一版采用外部进程插件","description":"","frontmatter":{},"headers":[],"relativePath":"zh/adr/ADR-0002-why-external-process-plugins.md","filePath":"zh/adr/ADR-0002-why-external-process-plugins.md","lastUpdated":0}`),a={name:`zh/adr/ADR-0002-why-external-process-plugins.md`};function o(r,i,a,o,s,c){return n(),e(`div`,null,[...i[0]||=[t(`<h1 id="adr-0002-为什么第一版采用外部进程插件" tabindex="-1">ADR-0002: 为什么第一版采用外部进程插件 <a class="header-anchor" href="#adr-0002-为什么第一版采用外部进程插件" aria-label="Permalink to “ADR-0002: 为什么第一版采用外部进程插件”">​</a></h1><ul><li>状态：已接受</li><li>日期：2026-10-31</li><li>关联：docs/guide/plugins.md §4，ADR-0003</li></ul><h2 id="背景" tabindex="-1">背景 <a class="header-anchor" href="#背景" aria-label="Permalink to “背景”">​</a></h2><p>插件要承载任意探测与恢复逻辑（mihomo、cloudflared、OpenClash、自定义脚本）， 作者语言不可预知，且插件代码质量不可控：会崩溃、会卡死、会写坏输出。</p><h2 id="决策" tabindex="-1">决策 <a class="header-anchor" href="#决策" aria-label="Permalink to “决策”">​</a></h2><p>插件是独立子进程，经 stdio 与核心对话（custos-plugin-host）： <code>PluginSupervisor</code> 负责启动/握手/能力校验/崩溃重启（滚动窗口 + 放弃标记）， 核心进程永不因插件死亡而退出；插件崩溃后其资源按 §4.5 标记不可探测并通知。</p><h2 id="替代方案" tabindex="-1">替代方案 <a class="header-anchor" href="#替代方案" aria-label="Permalink to “替代方案”">​</a></h2><ul><li><strong>进程内动态库（dlopen/cdylib）</strong>：一次崩溃即核心崩溃，隔离为零；ABI 脆弱； 与&quot;插件崩溃不退出核心&quot;的 P1 验收门直接冲突。</li><li><strong>纯内置（不开放插件）</strong>：扩展只能改核心发版；社区无法贡献场景化能力。</li><li><strong>WASM</strong>：沙箱好但宿主接口（文件/进程/网络）都要自建 ABI，第一版成本过高。</li></ul><h2 id="优缺点" tabindex="-1">优缺点 <a class="header-anchor" href="#优缺点" aria-label="Permalink to “优缺点”">​</a></h2><p>优点：故障域物理隔离；语言自由（任何能写 stdout 的语言）；崩溃重启策略可独立演化； 权限边界清晰（插件不持有核心内存与凭据）。 缺点：IPC 序列化开销（JSON 行协议）；进程生命周期管理复杂（僵尸、stderr 背压）； 握手/版本/能力校验需要协议纪律。</p><h2 id="后续影响" tabindex="-1">后续影响 <a class="header-anchor" href="#后续影响" aria-label="Permalink to “后续影响”">​</a></h2><ul><li>ADR-0003（JSON-RPC over stdio）实现协议层。</li><li>stderr 持续读取线程防止管道写满阻塞（tests: chatty_stderr_is_drained_and_capped）。</li><li>Python 入向脚本加载器（todo P1）复用同一契约：超时/权限/预算同口径。</li></ul>`,12)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};